      width: min(1120px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 1.25rem 0 3rem;
    }

    header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.75rem 0 1.5rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .brand-badge {
      display: inline-grid;
      place-items: center;
      width: 2.5rem;
      height: 2.5rem;
      border-radius: 0.9rem;
      background: linear-gradient(135deg, #315efb, #7c3aed);
      color: #fff;
      box-shadow: 0 14px 32px rgba(49, 94, 251, 0.28);
    }

    .meta-nav {
      color: var(--muted);
      font-size: 0.95rem;
    }

    main {
      outline: none;
    }

    .hero {
      display: grid;
      gap: 1.5rem;
      grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.9fr);
      align-items: start;
    }

    .preview-card,
    .details-card {
      background: var(--surface);
      backdrop-filter: blur(16px);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
