      bottom: 1rem;
      padding: 0.6rem 0.85rem;
      border-radius: 999px;
      background: rgba(15, 23, 42, 0.65);
      color: #fff;
      font-size: 0.92rem;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.75rem;
      justify-content: space-between;
      padding: 1rem 0.25rem 0.25rem;
    }

    .action-copy {
      color: var(--muted);
      font-size: 0.96rem;
    }

    .button-row {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    button {
      border: 0;
      border-radius: 999px;
      cursor: pointer;
      min-height: 2.9rem;
      padding: 0.8rem 1.2rem;
      transition: transform 150ms ease, background-color 150ms ease, box-shadow 150ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:disabled {
      cursor: not-allowed;
      transform: none;
      opacity: 0.65;
    }

    .secondary {
      background: #eef2ff;
      color: #314158;
    }

    .trigger,
    .danger {
      background: var(--danger-soft);
      color: var(--danger-strong);
      font-weight: 600;
    }

    .danger.confirm {
      background: var(--danger);
      color: #fff;
      box-shadow: 0 12px 28px rgba(217, 45, 32, 0.28);
    }

    .details-card {
      padding: 1.5rem;
      display: grid;
      gap: 1.2rem;
    }

    .eyebrow {
      display: inline-flex;
      width: fit-content;
      padding: 0.5rem 0.8rem;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent);
      font-weight: 700;
      font-size: 0.88rem;
      letter-spacing: 0.01em;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.6rem);
      line-height: 1.02;
      letter-spacing: -0.05em;
    }

    .lead {
      margin: 0;
      color: var(--muted);
      font-size: 1.05rem;
      max-width: 34ch;
    }

    .info-grid {
      display: grid;
      gap: 0.9rem;
    }

    .info-card {
      display: grid;
      gap: 0.25rem;
      padding: 1rem 1.1rem;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.68);
      border: 1px solid rgba(32, 52, 90, 0.08);
    }

    .info-card dt {
      color: var(--muted);
      font-size: 0.9rem;
    }

    .info-card dd {
      margin: 0;
      font-size: 1rem;
      font-weight: 600;
    }

    .status {
      min-height: 1.5rem;
      color: var(--accent);
      font-weight: 600;
    }

    dialog {
      width: min(92vw, 28rem);
      border: 0;
      border-radius: 1.5rem;
      padding: 0;
      background: var(--surface-strong);
      color: var(--text);
      box-shadow: 0 28px 100px rgba(15, 23, 42, 0.3);
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.55);
      backdrop-filter: blur(6px);
    }

    .dialog-body {
      padding: 1.5rem;
      display: grid;
      gap: 1rem;
    }

    .dialog-icon {
      display: inline-grid;
      place-items: center;
      width: 3rem;
      height: 3rem;
      border-radius: 1rem;
      background: var(--danger-soft);
      color: var(--danger);
      font-size: 1.25rem;
      font-weight: 700;
    }

    h2 {
      margin: 0;
      font-size: 1.45rem;
      letter-spacing: -0.03em;
    }

    .dialog-body p {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      flex-wrap: wrap;
      padding-top: 0.5rem;
    }

    .deleted .image-frame {
      filter: grayscale(1) opacity(0.5);
    }

    .deleted .image-label {
      background: rgba(180, 35, 24, 0.85);
    }

    @media (max-width: 760px) {
      .hero {
        grid-template-columns: 1fr;
      }

      .actions {
        align-items: flex-start;
      }

      .button-row,
      .dialog-actions {
        width: 100%;
      }

      .button-row button,
