        --border: ButtonBorder;
        --accent: LinkText;
        --danger: Mark;
        --danger-strong: MarkText;
        --focus: Highlight;
      }

      .preview-card,
      .details-card,
      .info-card,
      dialog,
      .skip-link {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      .brand-badge,
      .eyebrow,
      .secondary,
      .trigger,
      .danger.confirm,
      .image-label,
      .dialog-icon {
        forced-color-adjust: none;
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <div class="page-shell">
    <header>
      <div class="brand" aria-label="Pixel Library">
        <span class="brand-badge" aria-hidden="true">PL</span>
        <span>Pixel Library</span>
      </div>
      <nav class="meta-nav" aria-label="Primary">
        Image library / Preview
      </nav>
    </header>

    <main id="maincontent" tabindex="-1">
      <section class="hero" aria-labelledby="page-title">
        <article class="preview-card" id="preview-card" aria-labelledby="image-title">
          <figure>
            <div class="image-frame">
              <img
                id="preview-image"
                src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
                alt="Mountain lake at sunset with pine trees reflected in calm water"
              >
              <div class="image-label" id="image-title">Sunset reflections</div>
            </div>
          </figure>

          <div class="actions">
            <p class="action-copy" id="image-description">
              Shared in 3 collections and ready for licensing review.
            </p>
            <div class="button-row">
              <button type="button" class="secondary">Download</button>
              <button
                type="button"
                class="trigger"
                id="delete-trigger"
                aria-haspopup="dialog"
              >
                Delete image
              </button>
            </div>
          </div>
        </article>

        <aside class="details-card" aria-labelledby="page-title">
          <span class="eyebrow">Image preview</span>
          <div>
            <h1 id="page-title">Review before removing from your library</h1>
            <p class="lead">
              Inspect the image details, then delete it only if you are sure it should no longer be available in your workspace.
            </p>
          </div>

          <dl class="info-grid">
            <div class="info-card">
              <dt>Resolution</dt>
              <dd>5472 × 3648 px</dd>
            </div>
            <div class="info-card">
              <dt>Added by</dt>
              <dd>Design team</dd>
            </div>
            <div class="info-card">
              <dt>Last updated</dt>
              <dd>Today at 10:42 AM</dd>
            </div>
          </dl>

          <p class="status" id="status-message" aria-live="polite"></p>
        </aside>
      </section>
    </main>
  </div>

  <dialog
    id="delete-dialog"
    aria-labelledby="dialog-title"
    aria-describedby="dialog-description"
  >
    <div class="dialog-body">
      <span class="dialog-icon" aria-hidden="true">!</span>
      <div>
        <h2 id="dialog-title">Delete this image from your library?</h2>
      </div>
      <p id="dialog-description">
        This removes <strong>Sunset reflections</strong> from your library. This action cannot be undone.
      </p>
      <div class="dialog-actions">
        <button type="button" class="secondary" id="cancel-button" autofocus>Cancel</button>
        <button type="button" class="danger confirm" id="confirm-delete">Delete image</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('delete-trigger');
    const cancelButton = document.getElementById('cancel-button');
    const confirmDeleteButton = document.getElementById('confirm-delete');
    const previewCard = document.getElementById('preview-card');
    const previewImage = document.getElementById('preview-image');
    const imageTitle = document.getElementById('image-title');
    const imageDescription = document.getElementById('image-description');
    const statusMessage = document.getElementById('status-message');

    trigger.addEventListener('click', () => {
      dialog.showModal();
    });

    cancelButton.addEventListener('click', () => {
      dialog.close('cancel');
    });

    confirmDeleteButton.addEventListener('click', () => {
      previewCard.classList.add('deleted');
      previewImage.alt = 'Deleted image placeholder for Sunset reflections';
      imageTitle.textContent = 'Deleted from library';
      imageDescription.textContent = 'This image has been removed and is no longer available in your library.';
      trigger.disabled = true;
      trigger.textContent = 'Image deleted';
      statusMessage.textContent = 'Image deleted from your library.';
      dialog.close('delete');
    });
  </script>
</body>
</html>
